## Refactored `app.js`

```js
// app.js – production‑ready starter
// ---------------------------------------------------
// Security‑focused improvements:
//   • Helmet for secure HTTP headers
//   • CORS whitelist
//   • Rate limiting
//   • Centralised error handling
//   • Input validation (example for future routes)
//   • Structured logging with pino
//   • Graceful shutdown on uncaught errors
// ---------------------------------------------------

require('dotenv').config();          // Loads .env (PORT, CORS_ORIGINS, etc.)

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');
const pino = require('pino');
const pinoHttp = require('pino-http');

const logger = pino({ level: process.env.LOG_LEVEL || 'info' });
const app = express();

// ------------------------------------------------------------------
// Middleware stack
// ------------------------------------------------------------------

// Secure HTTP headers
app.use(helmet());

// Structured request logging (adds `req.log`)
// (In production you may pipe logs to a log aggregator.)
app.use(pinoHttp({ logger }));

// Body parsing (JSON only; limit size to prevent DoS via large payloads)
app.use(express.json({ limit: '100kb' }));

// CORS – whitelist via env var (comma‑separated)
const allowedOrigins = (process.env.CORS_ORIGINS || '').split(',').map(o => o.trim()).filter(Boolean);
app.use(
  cors({
    origin: (origin, cb) => {
      // Allow non‑browser (e.g., curl/postman) requests when `origin` is undefined
      if (!origin) return cb(null, true);
      if (allowedOrigins.includes(origin)) return cb(null, true);
      return cb(new Error('Not allowed by CORS'));
    },
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    credentials: true,
  })
);

// Rate limiting – 100 req/min per IP for the whole API
const apiLimiter = rateLimit({
  windowMs: 60_000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use(apiLimiter);

// ------------------------------------------------------------------
// Helper: validation error formatter
// ------------------------------------------------------------------
function handleValidationErrors(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    // Do **not** expose internal field names, just report a generic message
    return res.status(400).json({ error: 'Invalid request parameters', details: errors.array() });
  }
  next();
}

// ------------------------------------------------------------------
// Routes
// ------------------------------------------------------------------

// Health check – minimal, no sensitive data
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example static data route – keep data immutable
app.get('/users', (req, res) => {
  // In a real app, pull from a DB and *sanitize* fields before sending
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

/* ------------------------------------------------------------------
   Future endpoint example that demonstrates input validation.
   Uncomment & adapt as you introduce new routes that accept data.
------------------------------------------------------------------ */
// app.post(
//   '/register',
//   [
//     body('email').isEmail().normalizeEmail(),
//     body('password').isLength({ min: 8 }).trim(),
//     body('name').isString().trim().escape(),
//   ],
//   handleValidationErrors,
//   async (req, res, next) => {
//     try {
//       const { email, password, name } = req.body;
//       // TODO: hash password, store user, etc.
//       res.status(201).json({ message: 'User created' });
//     } catch (err) {
//       next(err); // forward to central error handler
//     }
//   }
// );

// ------------------------------------------------------------------
// Central error‑handling middleware
// ------------------------------------------------------------------
app.use((err, req, res, next) => {
  // Log the full stack server‑side, but never expose it to the client
  req.log.error({ err }, 'Request error');

  const status = err.status || 500;
  const message = status === 500 ? 'Internal server error' : err.message;

  res.status(status).json({
    error: message,
    // In non‑production you may include err.stack for debugging:
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack }),
  });
});

// ------------------------------------------------------------------
// Server bootstrap
// ------------------------------------------------------------------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server listening on port ${PORT}`);
});

// Graceful shutdown on fatal errors / SIGTERM
function shutdown(signal) {
  logger.warn(`${signal} received – shutting down gracefully`);
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
  // Force shutdown after 10 seconds
  setTimeout(() => process.exit(1), 10_000).unref();
}
process.on('SIGINT', () => shutdown('SIGINT'));
process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('unhandledRejection', (reason) => {
  logger.error({ reason }, 'Unhandled Promise Rejection');
  // Attempt graceful shutdown
  shutdown('unhandledRejection');
});
process.on('uncaughtException', (err) => {
  logger.fatal({ err }, 'Uncaught Exception');
  shutdown('uncaughtException');
});

module.exports = app;
```

### What changed & why

1. **Environment config (`dotenv`)** – Keeps secrets (port, CORS whitelist, log level) out of source control.
2. **Helmet** – Adds `Content‑Security‑Policy`, `X‑Frame‑Options`, `X‑Content‑Type‑Options`, etc.
3. **CORS** – Only origins listed in `CORS_ORIGINS` are allowed. This prevents any third‑party website from calling the API via browsers.
4. **Rate limiting** – Mitigates brute‑force and simple DoS attacks.
5. **Body‑parser limit** – Prevents memory exhaustion from gigantic JSON payloads.
6. **Structured logging** – `pino` (or `winston`) gives timestamps, request IDs, and log levels, which is essential for audit trails.
7. **Input validation scaffold** – Demonstrates how to use `express-validator` (or you could switch to `Joi`/`zod`). Even static routes benefit from a generic validation wrapper for future growth.
8. **Central error handler** – Guarantees that every thrown error (sync or async) is caught, logged, and transformed into a safe JSON response.
9. **Graceful shutdown** – Handles SIGTERM/SIGINT (common in containers/K8s) and uncaught exceptions, allowing in‑flight requests to finish.
10. **Port from env** – Enables the same container to run on any port required by the host environment.

### Quick checklist for you

- **Add a `.env`** (or match your deployment system) with at least:
  ```dotenv
  PORT=3000
  CORS_ORIGINS=http://localhost:3000   # comma‑separated list
  LOG_LEVEL=info
  NODE_ENV=production
  ```
- Run `npm install helmet cors express-rate-limit express-validator pino pino-http dotenv`.
- Run `npm audit` regularly and address vulnerabilities (`npm audit fix` or manual upgrades).
- If you later connect to a database, always use parameterised queries / ORM sanitisation.
- Consider adding **Content‑Security‑Policy** adjustments in `helmet` if you ever serve HTML.
- If you expose the API publicly, put it behind a reverse‑proxy (NGINX/Traefik) that terminates TLS and adds additional rate‑limiting / bot‑detection.

---

**Bottom line:** The refactor adds a defensive layer around every request, ensures that errors are logged but not leaked, validates any future user‑supplied data, and follows OWASP‑recommended hardening practices. Feel free to cherry‑pick the pieces that fit your current project scope, but for a production service all of the above (or equivalents) should be in place.

