## 2. Security‑focused middleware

```js
// Add these near the top, before any routes are mounted
const helmet   = require('helmet');      // Secure HTTP headers
const cors     = require('cors');        // Configure cross‑origin requests
const rateLimit = require('express-rate-limit'); // Basic DoS protection
const xssClean = require('xss-clean');   // Basic XSS sanitisation
const hpp      = require('hpp');         // Prevent HTTP Parameter Pollution
```

```js
// Security headers (Helmet)
app.use(helmet());

// CORS – restrict to trusted origins in production
app.use(cors({
  origin: process.env.CORS_ORIGIN || '*', // change '*' to your front‑end URL
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  credentials: true,
}));

// Rate limiting – adjust limits to your traffic profile
