const express = require('express');
const helmet = require('helmet');
const cors   = require('cors');
const rateLimit = require('express-rate-limit');
const compression = require('compression');

const app = express();

app.disable('x-powered-by');          // hide Express version
app.use(helmet());                    // secure HTTP headers
app.use(express.json());              // parse JSON bodies
app.use(compression());               // gzip responses

// CORS – tighten to only allowed origins
const allowedOrigins = ['https://my-frontend.example.com'];
app.use(cors({
  origin: (origin, callback) => callback(null, allowedOrigins.includes(origin)),
  credentials: true,
}));
```

---

## 2. Centralised error handling  

Express won’t automatically catch async errors, nor will it give a consistent JSON error shape. Create a **wrapper** for async route handlers and a **global error‑handler** middleware.

```js
// async wrapper – catches rejected promises
const asyncHandler = fn => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);

// Global error responder
app.use((err, req, res, next) => {
  // Log the error (use a real logger in prod)
  console.error(err);

  // Do not leak stack traces in production
  const isProd = process.env.NODE_ENV === 'production';
  const status = err.status || 500;
  const message = isProd ? 'Internal Server Error' : err.message;

  res.status(status).json({ error: message });
});
```

Wrap each route with `asyncHandler` (even the simple ones, it costs nothing) so any future async work is safe:

```js
app.get('/health', asyncHandler(async (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
}));
```

---

## 3. Input validation (even if you only have GET now)  

If you ever expose query‑string or body parameters, validate **strictly** before using them. Two popular options:

* **express-validator** – declarative, works with the request object.
* **Joi** (or **@hapi/joi**) – schema‑first, great for larger payloads.

### Example with `express-validator`

```js
const { query, validationResult } = require('express-validator');

app.get(
  '/users',
  //  ← validation chain (example: optional “page” query param must be an integer >=1)
  query('page')
    .optional()
    .isInt({ min: 1 })
    .toInt()
    .withMessage('page must be a positive integer'),
  asyncHandler(async (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      // 400 Bad Request + details of what failed
      return res.status(400).json({ errors: errors.array() });
    }

    // safe to use req.query.page now – either undefined or a parsed int
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob',   email: 'bob@example.com' },
    ];
    res.json(users);
  })
);
```

### Example with Joi (for a POST endpoint)

```js
const Joi = require('joi');

const userSchema = Joi.object({
  name:  Joi.string().min(2).max(100).required(),
  email: Joi.string().email().required(),
});

app.post(
  '/users',
  asyncHandler(async (req, res) => {
    const { error, value } = userSchema.validate(req.body, { abortEarly: false });
    if (error) {
      return res.status(400).json({ errors: error.details.map(d => d.message) });
    }

    // value is guaranteed to conform to the schema
    // … insert into DB, etc.
    res.status(201).json({ id: 3, ...value });
  })
);
```

Even if you don’t have any parameters *right now*, scaffolding the validation pipeline prevents future “forgot‑to‑validate” bugs.

---

## 4. Sanitize data that leaves the server  

When you send back data that originated from user input (e.g. usernames, comments), **HTML‑escape** it before rendering on the client side. In a pure JSON API you’re safe from XSS *as long as* the client treats the payload as data, not as HTML. Still, passing raw HTML in fields is a red flag – consider stripping/escaping HTML tags with a library like `sanitize-html` if you ever accept rich text.

---

## 5. Use environment‑driven configuration  

Hard‑coding the port or other secrets is fine for a demo, but production should read from `process.env`. Also, **disable stack‑traces** in production as shown in the error handler.

```js
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));
```

