## 4. Suggested Refactored `app.js`

Below is a **drop‑in** version that incorporates the above suggestions while preserving the original behaviour.

```js
// app.js
'use strict';

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const pino = require('pino');
const logger = pino({ level: process.env.LOG_LEVEL || 'info' });

const app = express();

// ---------- Basic security hardening ----------
app.disable('x-powered-by');                // Hide framework info
app.use(helmet());                          // Security headers (incl. CSP)
app.use(
  cors({
    origin: process.env.CORS_ORIGIN?.split(',') || [], // whitelist from env
    credentials: true,
  })
);

// ---------- Rate limiting ----------
const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---------- Body parsing (if you add POST/PUT later) ----------
app.use(express.json({ limit: '10kb' })); // limit payload size

// ---------- Health endpoint ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// ---------- Users endpoint (static for now) ----------
app.get('/users', (req, res, next) => {
  try {
    // In a real app you’d fetch from DB & maybe paginate/validate query params
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  } catch (err) {
    // Forward any unexpected error to the global handler
    next(err);
  }
});

// ---------- Global error handler ----------
app.use((err, req, res, next) => {
  // Log with context
  logger.error({ err, method: req.method, url: req.originalUrl }, 'Request error');

  // Do not leak internal details in production
  const isProd = process.env.NODE_ENV === 'production';
  const response = {
    message: err.message || 'Internal Server Error',
    ...(isProd ? {} : { stack: err.stack }),
  };
  res.status(err.status || 500).json(response);
});

// ---------- Graceful shutdown ----------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

// Handle termination signals (SIGINT, SIGTERM)
const shutdown = () => {
  logger.info('Graceful shutdown initiated');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
};
process.on('SIGINT', shutdown);
process.on('SIGTERM', shutdown);

module.exports = app;
```

### What changed?

| Category | Change |
|----------|--------|
| **Security headers** | `helmet()` + disabled `x-powered-by`. |
| **CORS** | Configurable whitelist via `process.env.CORS_ORIGIN`. |
| **Rate limiting** | 100 req/min per IP. |
| **Body size limit** | `express.json({ limit: '10kb' })`. |
| **Error handling** | Central error middleware that logs with `pino` and hides stack traces in production. |
| **Logging** | Structured logging using `pino`. |
| **Port configuration** | Uses `process.env.PORT`. |
| **Graceful shutdown** | Listens for SIGINT/SIGTERM to close the server cleanly. |
| **Future‑proof validation** | Placeholder `try/catch` + comment where you’d plug in validation libraries. |

