// app.js
/**
 * Secure & robust Express starter.
 * --------------------------------------------------------------
 * 1️⃣ Centralised error handling
 * 2️⃣ Security‑focused middleware (helmet, cors, rate‑limit)
 * 3️⃣ Input validation scaffolding (using Joi)
 * 4️⃣ Configurable environment (PORT, NODE_ENV)
 * 5️⃣ Structured logging (pino)
 * --------------------------------------------------------------
 */

'use strict';

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const pino = require('pino');
const pinoHttp = require('pino-http'); // request logger
const asyncHandler = require('express-async-handler'); // wraps async routes
const Joi = require('joi'); // validation library

// ---------- Configuration ----------
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const isProd = NODE_ENV === 'production';

// ---------- Logger ----------
const logger = pino({
  level: isProd ? 'info' : 'debug',
  prettyPrint: !isProd,
});

// ---------- Express app ----------
const app = express();

// ------- Middleware stack -------
app.use(pinoHttp({ logger }));          // request logger
app.use(helmet());                      // security headers
app.use(express.json());                // parse JSON bodies
app.use(express.urlencoded({ extended: false }));

// CORS – adjust `origin` to match your front‑end domains
app.use(
  cors({
    origin: process.env.CORS_ORIGIN || '*', // tighten in prod!
    methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization'],
  })
);

// Rate limiting – 100 req/min per IP (tune as needed)
const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    res.status(429).json({ error: 'Too many requests – please try again later.' });
  },
});
app.use(limiter);

// ---------- Validation schemas ----------
const emptySchema = Joi.object().empty(); // placeholder for routes that currently need no input

// ---------- Routes ----------
app.get(
  '/health',
  asyncHandler(async (req, res) => {
    // No user input → no validation required, but we could still enforce an empty schema for consistency
    await emptySchema.validateAsync(req.query); // will always pass

    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      env: NODE_ENV,
    });
  })
);

app.get(
  '/users',
  asyncHandler(async (req, res) => {
    // Example: allow pagination params – validate them
    const schema = Joi.object({
      page: Joi.number().integer().min(1).default(1),
      limit: Joi.number().integer().min(1).max(100).default(20),
    });
    const { page, limit } = await schema.validateAsync(req.query);

    // In a real app you'd fetch from DB with proper pagination / sanitisation
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Simple pagination logic for illustration
    const start = (page - 1) * limit;
    const paged = users.slice(start, start + limit);

    res.json(paged);
  })
);

// ---------- 404 handler ----------
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// ---------- Central error handler ----------
app.use((err, req, res, next) => {
  // Log the error (including stack in dev)
  logger.error({ err, reqId: req.id }, err.message);

  // Hide internal details in production
  const status = err.status || 500;
  const message = isProd ? 'Internal server error' : err.message;

  res.status(status).json({ error: message });
});

// ---------- Server bootstrap ----------
const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} (${NODE_ENV})`);
});

/* Graceful shutdown – important for containers/k8s */
function gracefulShutdown() {
  logger.info('Received shutdown signal – closing HTTP server...');
  server.close(() => {
    logger.info('HTTP server closed. Exiting process.');
    process.exit(0);
  });

  // Force exit if server does not close within 10 seconds
  setTimeout(() => {
    logger.warn('Force‑exiting after timeout.');
    process.exit(1);
  }, 10_000);
}
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);

module.exports = app;
```

### What changed & why

